// Not a copy of three.js — an alias.
//
// In the browser, `three` is resolved by the import map in index.html, which
// points at this repository's own build. Node has no import map, so a bare
// `from 'three'` in src/player.js cannot be resolved when a self-check in
// tools/ imports it, and the checks that matter most — walking the demo route
// through the REAL movement resolver and the REAL edge gluings — would be
// impossible to write without either duplicating the physics or stubbing it.
//
// This re-exports the exact same build the browser loads, so there is one
// three.js in the repository and no chance of the tests running against a
// different version from the page.
export * from '../../../../build/three.module.js';
